def compute(vars):
    loans = vars["v1"]
    total_assets_pledged = vars["v2"]
    if total_assets_pledged == 0:
        return None
    ratio = loans / total_assets_pledged
    percentage = ratio * 100
    return {
        "value": percentage,
        "trace": {
            "loans": loans,
            "total_assets_pledged": total_assets_pledged,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
